//      before it can pass the handle over the FFI to Rust.
//    * Thread B calls `destroy` and frees the underlying Rust struct.
//    * Thread A resumes, passing the already-read handle value to Rust and triggering
//      a use-after-free.
//
// One possible solution would be to use a `ReadWriteLock`, with each method call taking
// a read lock (and thus allowed to run concurrently) and the special `destroy` method
// taking a write lock (and thus blocking on live method calls). However, we aim not to
// generate methods with any hidden blocking semantics, and a `destroy` method that might
// block if called incorrectly seems to meet that bar.
//
// So, we achieve our goals by giving each instance an associated `AtomicLong` counter to track
// the number of in-flight method calls, and an `AtomicBoolean` flag to indicate whether `destroy`
// has been called. These are updated according to the following rules:
//
//    * The initial value of the counter is 1, indicating a live object with no in-flight calls.
//      The initial value for the flag is false.
//
//    * At the start of each method call, we atomically check the counter.
//      If it is 0 then the underlying Rust struct has already been destroyed and the call is aborted.
//      If it is nonzero them we atomically increment it by 1 and proceed with the method call.
//
//    * At the end of each method call, we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
//    * When `destroy` is called, we atomically flip the flag from false to true.
//      If the flag was already true we silently fail.
//      Otherwise we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
// Astute readers may observe that this all sounds very similar to the way that Rust's `Arc<T>` works,
// and indeed it is, with the addition of a flag to guard against multiple calls to `destroy`.
//
// The overall effect is that the underlying Rust struct is destroyed only when `destroy` has been
// called *and* all in-flight method calls have completed, avoiding violating any of the expectations
// of the underlying Rust code.
//
// This makes a cleaner a better alternative to _not_ calling `destroy()` as
// and when the object is finished with, but the abstraction is not perfect: if the Rust object's `drop`
// method is slow, and/or there are many objects to cleanup, and it's on a low end Android device, then the cleaner
// thread may be starved, and the app will leak memory.
//
// In this case, `destroy`ing manually may be a better solution.
//
// The cleaner can live side by side with the manual calling of `destroy`. In the order of responsiveness, uniffi objects
// with Rust peers are reclaimed:
//
// 1. By calling the `destroy` method of the object, which calls `rustObject.free()`. If that doesn't happen:
// 2. When the object becomes unreachable, AND the Cleaner thread gets to call `rustObject.free()`. If the thread is starved then:
// 3. The memory is reclaimed when the process terminates.
//
// [1] https://stackoverflow.com/questions/24376768/can-java-finalize-an-object-when-it-is-still-in-scope/24380219
//


public interface StoreInterface {
    
    /**
     * Adds an event of the user's own to a day, past or future: something
     * that was never in a calendar, or a calendar this device can't read.
     */
    fun `addOwnEvent`(`journalId`: kotlin.String?, `date`: kotlin.String, `event`: OwnEvent): KeptEvent
    
    /**
     * The day's kept events, and suggestions from `events` (the device's
     * calendar for that day, already fetched by the app). Kept events seen
     * in `events` are brought up to date on the way. Returns the kept ones
     * first; suggestions leave out cancelled events and any already kept.
     */
    fun `calendarDay`(`journalId`: kotlin.String?, `date`: kotlin.String, `events`: List<CalendarEvent>): CalendarDay
    
    /**
     * Keeps a calendar event on a journal day, and tracks it from then on.
     * Keeping one that was kept and then removed brings it back, note and all.
     */
    fun `keepCalendarEvent`(`journalId`: kotlin.String?, `date`: kotlin.String, `event`: CalendarEvent): KeptEvent
    
    /**
     * Events kept on one day, for showing without asking the calendar (a
     * device without calendar access, or before permission is granted).
     */
    fun `keptCalendarEvents`(`journalId`: kotlin.String?, `date`: kotlin.String): List<KeptEvent>
    
    /**
     * Brings kept events up to date with what the calendar has now. An
     * event that wasn't found counts as cancelled only on the device that
     * kept it, since another device may simply not have that calendar.
     * Returns how many kept events changed.
     */
    fun `refreshCalendarEvents`(`lookups`: List<CalendarLookup>): kotlin.UInt
    
    /**
     * Stops tracking a kept event and takes it off the day.
     */
    fun `removeCalendarEvent`(`id`: kotlin.String)
    
    /**
     * The user's own note on a kept event; empty clears it.
     */
    fun `setCalendarEventNote`(`id`: kotlin.String, `note`: kotlin.String?)
    
    /**
     * Every kept event whose key starts with `key_prefix` ("apple:",
     * "android:"), for the app to look up and pass to
     * `refresh_calendar_events`.
     */
    fun `trackedCalendarEvents`(`keyPrefix`: kotlin.String): List<KeptEvent>
    
    /**
     * Changes an event the user added by hand. Kept calendar events follow
     * their calendar instead, so they can't be edited here.
     */
    fun `updateOwnEvent`(`id`: kotlin.String, `event`: OwnEvent): KeptEvent
    
    /**
     * Whether the password is right, without opening anything.
     */
    fun `checkLockPassword`(`password`: kotlin.String): kotlin.Boolean
    
    /**
     * Whether the day has a locked note, for showing its tile.
     */
    fun `hasLockedNote`(`journalId`: kotlin.String?, `date`: kotlin.String): kotlin.Boolean
    
    fun `lockStatus`(): LockStatus
    
    /**
     * The day's locked note, opened with `password`; none if the day has
     * none. A wrong password is a crypto error ("wrong password").
     */
    fun `lockedNote`(`journalId`: kotlin.String?, `date`: kotlin.String, `password`: kotlin.String): kotlin.String?
    
    /**
     * For a forgotten password: deletes every locked note and the password,
     * and turns locked notes off. Nothing else in the journal changes.
     */
    fun `resetLock`()
    
    /**
     * Shows or hides locked notes. Turning them on needs a password set.
     */
    fun `setLockEnabled`(`enabled`: kotlin.Boolean)
    
    /**
     * Sets the lock password, or changes it (`current` is the old one).
     * Changing it re-seals every locked note under the new password. Also
     * turns locked notes on.
     */
    fun `setLockPassword`(`current`: kotlin.String?, `newPassword`: kotlin.String)
    
    /**
     * Saves the day's locked note under `password`. Empty text removes it.
     */
    fun `setLockedNote`(`journalId`: kotlin.String?, `date`: kotlin.String, `password`: kotlin.String, `text`: kotlin.String)
    
    /**
     * Keeps a photo on a journal day. Keeping the same file on the same day
     * again (on any device) lands on the same row, bringing it back if it
     * had been removed.
     */
    fun `addDayPhoto`(`journalId`: kotlin.String?, `date`: kotlin.String, `photo`: NewPhoto): DayPhoto
    
    /**
     * The photos kept on one day, in the order they were taken.
     */
    fun `dayPhotos`(`journalId`: kotlin.String?, `date`: kotlin.String): List<DayPhoto>
    
    /**
     * Photos added here whose `source_ref` isn't known yet and whose local
     * asset id starts with `asset_prefix` ("apple:"), for the app to look up
     * when it comes to the front.
     */
    fun `photosAwaitingSourceRef`(`assetPrefix`: kotlin.String): List<PhotoAsset>
    
    /**
     * Takes a photo off its day, on every device. The files go too, unless
     * the same photo is still kept on another day.
     */
    fun `removeDayPhoto`(`id`: kotlin.String)
    
    /**
     * The user's caption on a photo; empty clears it.
     */
    fun `setPhotoCaption`(`id`: kotlin.String, `caption`: kotlin.String?)
    
    /**
     * Records where other devices can find a photo, once the app knows.
     */
    fun `setPhotoSourceRef`(`id`: kotlin.String, `sourceRef`: kotlin.String)
    
    /**
     * Merges rows from `pull_ops`, in the order the server returned them.
     */
    fun `applyIncoming`(`rows`: List<IncomingOps>): PullResult
    
    /**
     * Loads a snapshot from `get_snapshot`, then continue with `pull_ops`
     * from the returned cursor. Used by a new device, or by one whose
     * cursor fell behind compaction (`pull_ops` raised PT409).
     */
    fun `applySnapshot`(`seq`: kotlin.Long, `payload`: kotlin.String): PullResult
    
    /**
     * A new, empty entry. `date` is `YYYY-MM-DD`, `time` is `HH:MM`.
     */
    fun `createEntry`(`journalId`: kotlin.String?, `date`: kotlin.String, `time`: kotlin.String?): Entry
    
    fun `createJournal`(`name`: kotlin.String, `color`: kotlin.String?): Journal
    
    /**
     * All entries on one day, including any covering several days that
     * take it in, earliest first.
     */
    fun `day`(`date`: kotlin.String, `journalId`: kotlin.String?): List<EntrySummary>
    
    fun `defaultJournalId`(): kotlin.String
    
    /**
     * Soft delete; the entry stays in Trash for 30 days (SPEC.md §6.2).
     */
    fun `deleteEntry`(`id`: kotlin.String)
    
    /**
     * This install's id, a UUID. Sent as `p_device_id` to every sync RPC.
     */
    fun `deviceId`(): kotlin.String
    
    /**
     * Deletes an entry that was opened and left untouched: no title, no
     * words, no rating, tags or favourite. The apps call this when the
     * editor closes. Returns whether it was deleted.
     */
    fun `discardIfEmpty`(`id`: kotlin.String): kotlin.Boolean
    
    fun `entry`(`id`: kotlin.String): Entry
    
    /**
     * Writes the journal (or one journal) to `path` in `format`. Name the
     * file with `export_extension(format)`.
     */
    fun `export`(`format`: ExportFormat, `path`: kotlin.String, `journalId`: kotlin.String?): ExportSummary
    
    fun `forgetJournalKey`()
    
    /**
     * A fresh journal key for a first-time sync setup. The app stores it in
     * the keychain and passes it to `set_journal_key` on every launch.
     */
    fun `generateJournalKey`(): kotlin.ByteArray
    
    /**
     * Imports `path` into `journal_id` (or each entry's own journal for a
     * Librelog export, else the default). Entries already imported are
     * skipped, so running this twice is safe. All or nothing.
     */
    fun `importFile`(`path`: kotlin.String, `journalId`: kotlin.String?): ImportResult
    
    fun `journals`(): List<Journal>
    
    /**
     * The value for `set_key_check`, sealed under the current key.
     */
    fun `keyCheck`(): kotlin.String
    
    /**
     * The key a typed recovery phrase stands for, to check against the
     * account's `key_check` before storing it.
     */
    fun `keyFromRecoveryPhrase`(`phrase`: kotlin.String): kotlin.ByteArray
    
    /**
     * True if `key_check` (from `register_device`) was sealed with `key`.
     */
    fun `keyMatches`(`key`: kotlin.ByteArray, `keyCheck`: kotlin.String): kotlin.Boolean
    
    /**
     * Calendar marks for one month, `YYYY-MM`. Entries covering several
     * days mark each of them.
     */
    fun `month`(`yearMonth`: kotlin.String, `journalId`: kotlin.String?): List<DayMark>
    
    fun `moveEntry`(`id`: kotlin.String, `journalId`: kotlin.String)
    
    /**
     * Entries from the same day and month in earlier years, newest year first.
     */
    fun `onThisDay`(`date`: kotlin.String): List<EntrySummary>
    
    fun `openDeviceName`(`sealed`: kotlin.String): kotlin.String
    
    /**
     * The next batch to push, or none if everything is pushed. Until
     * `push_succeeded` is called, this keeps returning the same batch.
     */
    fun `outgoingBatch`(`maxOps`: kotlin.UInt): OutgoingBatch?
    
    fun `pendingCount`(): kotlin.UInt
    
    /**
     * Reads `path` (a file, folder or zip) and says what importing it would
     * do, without changing anything.
     */
    fun `previewImport`(`path`: kotlin.String): ImportPreview
    
    /**
     * The server accepted `batch_id`: drop those ops from the queue.
     */
    fun `pushSucceeded`(`batchId`: kotlin.String)
    
    fun `recoveryPhrase`(): kotlin.String
    
    /**
     * Forgets all sync state for a fresh start with another account. The
     * journal itself is untouched; every row is queued to push again.
     */
    fun `resetSync`()
    
    /**
     * The user has reviewed an entry's conflicts: clear the banner.
     */
    fun `resolveConflicts`(`entryId`: kotlin.String)
    
    fun `restoreEntry`(`id`: kotlin.String)
    
    fun `revisions`(`entryId`: kotlin.String): List<Revision>
    
    /**
     * Saves the body; returns the new word count for the editor footer.
     */
    fun `saveBody`(`id`: kotlin.String, `body`: List<Block>): kotlin.UInt
    
    /**
     * The device's name, sealed for `register_device`'s `p_name_enc`.
     */
    fun `sealDeviceName`(`name`: kotlin.String): kotlin.String
    
    /**
     * Existing-device half of QR pairing: seals the journal key for the
     * device that showed `public_key`. Post the result with `pairing_fulfil`.
     */
    fun `sealKeyForPairing`(`publicKey`: kotlin.ByteArray): kotlin.String
    
    fun `search`(`query`: kotlin.String, `limit`: kotlin.UInt): List<SearchHit>
    
    /**
     * Moves an entry. One covering several days keeps its length.
     */
    fun `setDateTime`(`id`: kotlin.String, `date`: kotlin.String, `time`: kotlin.String?)
    
    /**
     * Makes an entry cover every day up to `end_date`, or just its own day
     * when none. An end on or before the start day clears it.
     */
    fun `setEndDate`(`id`: kotlin.String, `endDate`: kotlin.String?)
    
    fun `setFavorite`(`id`: kotlin.String, `favorite`: kotlin.Boolean)
    
    fun `setJournalKey`(`key`: kotlin.ByteArray)
    
    /**
     * Rating from 0 to 5 in half steps, or none to clear it.
     */
    fun `setRating`(`id`: kotlin.String, `rating`: kotlin.Double?)
    
    /**
     * Sets a synced setting; none goes back to the default.
     */
    fun `setSetting`(`key`: kotlin.String, `value`: kotlin.String?)
    
    fun `setTitle`(`id`: kotlin.String, `title`: kotlin.String?)
    
    /**
     * A synced setting, or none if never set. Keys are dotted names the apps
     * agree on (docs/appearance.md lists them).
     */
    fun `setting`(`key`: kotlin.String): kotlin.String?
    
    /**
     * The whole synced state, sealed, for `put_snapshot` (SPEC.md §12.5).
     * Upload one when `pull_ops` has returned a few thousand ops since the
     * last snapshot; the server then trims the log below `seq`.
     */
    fun `snapshot`(): OutgoingSnapshot
    
    /**
     * Totals and streaks. `today` is the device's local date.
     */
    fun `stats`(`today`: kotlin.String): Stats
    
    /**
     * Where the last pull ended: pass as `p_after` to `pull_ops`.
     */
    fun `syncCursor`(): kotlin.Long
    
    fun `tagEntry`(`entryId`: kotlin.String, `tagId`: kotlin.String, `value`: kotlin.String?)
    
    /**
     * Returns the tag with this name (any case), creating it if needed. The
     * id derives from the lowercased name, so two devices that each create
     * "Run" offline end up with one tag, not two.
     */
    fun `tagNamed`(`name`: kotlin.String): Tag
    
    fun `tags`(): List<Tag>
    
    /**
     * Newest first, `limit` at a time. Pass the last row back as `after`.
     */
    fun `timeline`(`filter`: TimelineFilter, `after`: TimelineCursor?, `limit`: kotlin.UInt): List<EntrySummary>
    
    fun `untagEntry`(`entryId`: kotlin.String, `tagId`: kotlin.String)
    
    companion object
}

open class Store: Disposable, AutoCloseable, StoreInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_librelog_core_fn_free_store(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_librelog_core_fn_clone_store(handle, status)
        }
    }

    
    /**
     * Adds an event of the user's own to a day, past or future: something
     * that was never in a calendar, or a calendar this device can't read.
     */
    @Throws(CoreException::class)override fun `addOwnEvent`(`journalId`: kotlin.String?, `date`: kotlin.String, `event`: OwnEvent): KeptEvent {
            return FfiConverterTypeKeptEvent.lift(
    callWithHandle {
    uniffiRustCallWithError(CoreException) { _status ->
    UniffiLib.uniffi_librelog_core_fn_method_store_add_own_event(
        it,
        
        FfiConverterOptionalString.lower(`journalId`),
        FfiConverterString.lower(`date`),
        FfiConverterTypeOwnEvent.lower(`event`),_status)
}
    }
    )
    }
    

    
