sealed class BlockKind {
    
    object Paragraph : BlockKind()
    
    
    data class Heading(
        val `level`: kotlin.UByte) : BlockKind()
        
    {
        

        companion object
    }
    
    object Bullet : BlockKind()
    
    
    object Numbered : BlockKind()
    
    
    data class Check(
        val `checked`: kotlin.Boolean) : BlockKind()
        
    {
        

        companion object
    }
    
    object Quote : BlockKind()
    
    
    object Code : BlockKind()
    
    
    object Rule : BlockKind()
    
    
    /**
     * An attachment shown inline; `text` is its caption.
     */
    data class Image(
        val `attachmentId`: kotlin.String) : BlockKind()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeBlockKind : FfiConverterRustBuffer<BlockKind>{
    override fun read(buf: ByteBuffer): BlockKind {
        return when(buf.getInt()) {
            1 -> BlockKind.Paragraph
            2 -> BlockKind.Heading(
                FfiConverterUByte.read(buf),
                )
            3 -> BlockKind.Bullet
            4 -> BlockKind.Numbered
            5 -> BlockKind.Check(
                FfiConverterBoolean.read(buf),
                )
            6 -> BlockKind.Quote
            7 -> BlockKind.Code
            8 -> BlockKind.Rule
            9 -> BlockKind.Image(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: BlockKind): ULong = when(value) {
        is BlockKind.Paragraph -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is BlockKind.Heading -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUByte.allocationSize(value.`level`)
            )
        }
        is BlockKind.Bullet -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is BlockKind.Numbered -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is BlockKind.Check -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.`checked`)
            )
        }
        is BlockKind.Quote -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is BlockKind.Code -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is BlockKind.Rule -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is BlockKind.Image -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`attachmentId`)
            )
        }
    }

    override fun write(value: BlockKind, buf: ByteBuffer) {
        when(value) {
            is BlockKind.Paragraph -> {
                buf.putInt(1)
                Unit
            }
            is BlockKind.Heading -> {
                buf.putInt(2)
                FfiConverterUByte.write(value.`level`, buf)
                Unit
            }
            is BlockKind.Bullet -> {
                buf.putInt(3)
                Unit
            }
            is BlockKind.Numbered -> {
                buf.putInt(4)
                Unit
            }
            is BlockKind.Check -> {
                buf.putInt(5)
                FfiConverterBoolean.write(value.`checked`, buf)
                Unit
            }
            is BlockKind.Quote -> {
                buf.putInt(6)
                Unit
            }
            is BlockKind.Code -> {
                buf.putInt(7)
                Unit
            }
            is BlockKind.Rule -> {
                buf.putInt(8)
                Unit
            }
            is BlockKind.Image -> {
                buf.putInt(9)
                FfiConverterString.write(value.`attachmentId`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * Every error the core hands to the apps. Messages are for logs, not for
 * showing to users; the variant is what the UI branches on.
 */
sealed class CoreException(message: String): kotlin.Exception(message) {
        
        class Database(message: String) : CoreException(message)
        
        class NotFound(message: String) : CoreException(message)
        
        class Invalid(message: String) : CoreException(message)
        
        class Sync(message: String) : CoreException(message)
        
        class Crypto(message: String) : CoreException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        
            return when(buf.getInt()) {
            1 -> CoreException.Database(FfiConverterString.read(buf))
            2 -> CoreException.NotFound(FfiConverterString.read(buf))
            3 -> CoreException.Invalid(FfiConverterString.read(buf))
            4 -> CoreException.Sync(FfiConverterString.read(buf))
            5 -> CoreException.Crypto(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: CoreException): ULong {
        return 4UL
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.Database -> {
                buf.putInt(1)
                Unit
            }
            is CoreException.NotFound -> {
                buf.putInt(2)
                Unit
            }
            is CoreException.Invalid -> {
                buf.putInt(3)
                Unit
            }
            is CoreException.Sync -> {
                buf.putInt(4)
                Unit
            }
            is CoreException.Crypto -> {
                buf.putInt(5)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




